const rows = $input.item.json.rows || [];
const sorted = [...rows].sort((a,b) => b.clicks - a.clicks);
const top10 = sorted.slice(0, 10);

const totalClicks = rows.reduce((s, r) => s + r.clicks, 0);
const totalImpressions = rows.reduce((s, r) => s + r.impressions, 0);
const avgCtr = totalImpressions > 0 ? ((totalClicks / totalImpressions) * 100).toFixed(1) : 0;
const avgPos = rows.length > 0 ? (rows.reduce((s,r) => s + r.position, 0) / rows.length).toFixed(1) : 0;

const table = top10.map(r =>
  `| ${r.keys[0].substring(0,40)} | ${r.clicks} | ${r.impressions} | ${(r.ctr*100).toFixed(1)}% | ${r.position.toFixed(1)} |`
).join('\n');

return [{
  json: {
    summary: `📊 *Albanexa Search Console — Haftalık Özet*\n` +
      `📅 Son 7 gün\n\n` +
      `• Toplam tıklama: *${totalClicks}*\n` +
      `• Gösterim: *${totalImpressions}*\n` +
      `• Ort. CTR: *${avgCtr}%*\n` +
      `• Ort. Konum: *${avgPos}*\n\n` +
      `*Top 10 Sorgu:*\n` +
      `| Sorgu | Tık | Gösterim | CTR | Konum |\n` +
      `|---|---|---|---|---|\n` +
      table
  }
}];
